using Microsoft.EntityFrameworkCore;

namespace GoalStatsTrackerService.Model;

// IDs are generated by the client, so they are only guaranteed unique within a team
[PrimaryKey(nameof(TeamId), nameof(Id))]
public class Player
{
    public string TeamId { get; set; } = "";
    public string Id { get; set; } = "";
    public string Name { get; set; } = "";
    public string? Number { get; set; }
    /// <summary>Removed players are archived so old match stats keep their names.</summary>
    public bool Archived { get; set; }
}
